#include <DHT.h>
#define DHTPIN 2
#define DHTTYPE DHT11
DHT dht(DHTPIN, DHTTYPE);

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  float h = dht.readHumidity();
  float t = dht.readTemperature();
  if (isnan(h) || isnan(t)) {
    Serial.println("Lexim i dështuar");
    return;
  }
  Serial.print("T="); Serial.print(t);
  Serial.print("C H="); Serial.print(h); Serial.println("%");
  delay(2000);
}

