const int CLK = 2;
const int DT = 3;
const int SW = 4;
int lastCLK;

void setup() {
  Serial.begin(9600);
  pinMode(CLK, INPUT);
  pinMode(DT, INPUT);
  pinMode(SW, INPUT_PULLUP);
  lastCLK = digitalRead(CLK);
}

void loop() {
  int clk = digitalRead(CLK);
  if (clk != lastCLK && clk == HIGH) {
    if (digitalRead(DT) != clk) Serial.println("CW");
    else Serial.println("CCW");
  }
  lastCLK = clk;
  if (digitalRead(SW) == LOW) Serial.println("CLICK");
}

